use strict;
use warnings;
use ExtUtils::MakeMaker;

WriteMakefile(
    NAME             => 'Path::Clean',
    VERSION_FROM     => 'lib/Path/Clean.pm',
    MIN_PERL_VERSION => '5.008001',
    PREREQ_PM        => { 'URI' => '1.60' },
    TEST_REQUIRES    => { 'Test::More' => '0.88' },
);

package Path::Clean;
use strict;
use warnings;
use URI;

our $VERSION = '0.01';

sub normalize {
    my ($class, $path) = @_;
    $path =~ s{/+}{/}g;
    return $path;
}

1;

use strict;
use warnings;
use Test::More;
use Path::Clean;

# Normalisation of relative paths.

is(Path::Clean->normalize('a//b'), 'a/b', 'collapses double slashes');
# 9
# 10
# 11
# 12
# 13
is(Path::Clean->normalize('a/./b'), 'a/b', 'resolves dot segments');

done_testing();
